def main():
    data=load(APP_ASSET); patch=load(PATCH_ASSET)
    if data!=patch: raise SystemExit('app/patch diagnostics differ before batch11')
    if len(data.get('scenarios',[]))!=136: raise SystemExit('unexpected scenario count')
    by={s['id']:s for s in data['scenarios']}
    if not TARGETS<=by.keys(): raise SystemExit('missing batch11 scenarios')
    for sid in sorted(TARGETS):
        s=by[sid]; apply_route(s,**ROUTES[sid])
        if not s.get('actions'): s['actions']=[{}]
        s['actions'][0]={'summary':'Локализовать механический дефект по подтверждённым признакам и текущим нормативным границам; приложение не разрешает ремонт/обход либо движение сверх действующего source-bound решения.','sourceBound':False,'riskClass':'stop_and_report' if sid in {'ER-DIAG-104','ER-DIAG-105','ER-DIAG-108','ER-DIAG-109','ER-DIAG-110'} else 'normal','userFacingPolicy':'TRIAGE_ONLY_NO_REPAIR'}
        s['sourceAudit']={'auditedAt':V,'scope':'p0_mechanics_batch11','status':'IMPROVE','method':'current PTE + manufacturer + independent technical cross-check'}
        for r in (R6,R7,R8,TECH): addref(s,r)
        if sid=='ER-DIAG-103': addref(s,R1)
        if sid in {'ER-DIAG-104','ER-DIAG-105','ER-DIAG-106','ER-DIAG-107','ER-DIAG-108','ER-DIAG-109','ER-DIAG-110'}: addref(s,PTE)
        if sid=='ER-DIAG-110': addref(s,R2580)
        s['sourceAgeNote']='Batch11 27.09.2026: эксплуатационные границы колесных пар/подшипников — действующий ПТЭ №250. Заводские РЭ раннего исполнения используются для конструкции/признаков. №2580/р для толчка/схода остаётся source-bound по текущей редакции.'
    dump(APP_ASSET,data); dump(PATCH_ASSET,data)
    if APP_ASSET.read_bytes()!=PATCH_ASSET.read_bytes(): raise SystemExit('app/patch differ after batch11')
    print('ERMAK_P0_MECHANICS_BATCH11='+','.join(sorted(TARGETS)))

if __name__=='__main__': main()
